begin;
create extension if not exists pgtap with schema extensions;
select no_plan();
insert into auth.users(id,instance_id,aud,role,email,email_confirmed_at,created_at,updated_at) values('af200000-0000-4000-8000-000000000001','00000000-0000-0000-0000-000000000000','authenticated','authenticated','f2-owner@example.test',now(),now(),now()),('af200000-0000-4000-8000-000000000002','00000000-0000-0000-0000-000000000000','authenticated','authenticated','f2-secretary@example.test',now(),now(),now());
insert into public.organizations(id,name,slug,status) values('bf200000-0000-4000-8000-000000000001','F2 sintético','f2-synthetic','active'),('bf200000-0000-4000-8000-000000000002','F2 outro','f2-other','active');
insert into public.organization_units(id,organization_id,name,slug,unit_type) values('cf200000-0000-4000-8000-000000000001','bf200000-0000-4000-8000-000000000001','Sede F2','sede','headquarters'),('cf200000-0000-4000-8000-000000000002','bf200000-0000-4000-8000-000000000002','Outra F2','sede','headquarters');
insert into public.organization_memberships(organization_id,user_id,role,status,default_unit_id) values('bf200000-0000-4000-8000-000000000001','af200000-0000-4000-8000-000000000001','owner','active','cf200000-0000-4000-8000-000000000001'),('bf200000-0000-4000-8000-000000000001','af200000-0000-4000-8000-000000000002','secretary','active','cf200000-0000-4000-8000-000000000001');
select ok(not has_table_privilege('authenticated','private.finance_settlements','SELECT'),'baixas não expostas diretamente');
select ok(not has_function_privilege('authenticated','private.finance_f1_base(uuid,uuid[],text,jsonb)','EXECUTE'),'núcleo F1 sem bypass direto');
select ok(not has_function_privilege('anon','public.finance_f2(uuid,uuid,text,jsonb)','EXECUTE'),'visitante sem F2');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"af200000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select set_config('f2.org','bf200000-0000-4000-8000-000000000001',true);
select set_config('f2.unit','cf200000-0000-4000-8000-000000000001',true);
select lives_ok($$select public.finance_f1(current_setting('f2.org')::uuid,array[current_setting('f2.unit')::uuid],'catalog','{"id":"df200000-0000-4000-8000-000000000001","kind":"account","name":"Caixa F2"}')$$,'conta F1 compatível');
select lives_ok($$select public.finance_f1(current_setting('f2.org')::uuid,array[current_setting('f2.unit')::uuid],'catalog','{"id":"df200000-0000-4000-8000-000000000002","kind":"category","name":"Receitas F2","direction":"income"}')$$,'categoria de receita');
select lives_ok($$select public.finance_f1(current_setting('f2.org')::uuid,array[current_setting('f2.unit')::uuid],'catalog','{"id":"df200000-0000-4000-8000-000000000003","kind":"category","name":"Taxas F2","direction":"expense"}')$$,'categoria de despesa');
select set_config('f2.title',jsonb_build_object('id','ff200000-0000-4000-8000-000000000001','kind','income','amountCents','10000','description','Conta a receber sintética','account','df200000-0000-4000-8000-000000000001','category','df200000-0000-4000-8000-000000000002','competence',current_date,'due',current_date,'method','pix')::text,true);
select lives_ok($$select public.finance_f1(current_setting('f2.org')::uuid,array[current_setting('f2.unit')::uuid],'entry',current_setting('f2.title')::jsonb)$$,'previsão recebível');
select set_config('f2.pay',jsonb_build_object('id','ff200000-0000-4000-8000-000000000002','title','ff200000-0000-4000-8000-000000000001','version',1,'principal','4000','interest','100','fine','200','discount','300','fee','100','feeCategory','df200000-0000-4000-8000-000000000003','account','df200000-0000-4000-8000-000000000001','date',current_date,'method','pix','reason','Parcial sintética')::text,true);
select lives_ok($$select public.finance_f2(current_setting('f2.org')::uuid,current_setting('f2.unit')::uuid,'settle',current_setting('f2.pay')::jsonb)$$,'baixa parcial com encargos e taxa');
select lives_ok($$select public.finance_f2(current_setting('f2.org')::uuid,current_setting('f2.unit')::uuid,'settle',current_setting('f2.pay')::jsonb)$$,'reenvio exato não duplica');
select set_config('f2.query',jsonb_build_object('from',current_date,'to',current_date,'page',1)::text,true);
select is(public.finance_f1(current_setting('f2.org')::uuid,array[current_setting('f2.unit')::uuid],'snapshot',current_setting('f2.query')::jsonb)#>>'{summary,receivable}','6000','previsto é só saldo em aberto');
select is(public.finance_f1(current_setting('f2.org')::uuid,array[current_setting('f2.unit')::uuid],'snapshot',current_setting('f2.query')::jsonb)#>>'{summary,income}','4000','bruto exato');
select is(public.finance_f1(current_setting('f2.org')::uuid,array[current_setting('f2.unit')::uuid],'snapshot',current_setting('f2.query')::jsonb)#>>'{summary,expense}','100','taxa é despesa real');
select is(public.finance_f1(current_setting('f2.org')::uuid,array[current_setting('f2.unit')::uuid],'snapshot',current_setting('f2.query')::jsonb)#>>'{accounts,0,balanceCents}','3900','saldo líquido recebido');
select is(public.finance_f1(current_setting('f2.org')::uuid,array[current_setting('f2.unit')::uuid],'snapshot',current_setting('f2.query')::jsonb||'{"scope":"titles"}') ->>'total','1','lista de compromissos não duplica baixas');
select is(public.finance_f2(current_setting('f2.org')::uuid,current_setting('f2.unit')::uuid,'history','{"title":"ff200000-0000-4000-8000-000000000001"}')#>>'{payments,0,fee}','100','histórico revela taxa efetiva');
select throws_ok($$select public.finance_f2(current_setting('f2.org')::uuid,current_setting('f2.unit')::uuid,'settle',current_setting('f2.pay')::jsonb||'{"id":"ff200000-0000-4000-8000-000000000003"}')$$,'40001',null,'versão velha recusa segunda baixa');
select throws_ok($$select public.finance_f2(current_setting('f2.org')::uuid,current_setting('f2.unit')::uuid,'settle',current_setting('f2.pay')::jsonb||'{"principal":"4001"}')$$,'22023',null,'mesmo pedido adulterado é recusado');
select throws_ok($$select public.finance_f2(current_setting('f2.org')::uuid,current_setting('f2.unit')::uuid,'settle',current_setting('f2.pay')::jsonb||'{"id":"ff200000-0000-4000-8000-000000000003","version":2,"principal":"6001"}')$$,'22023',null,'não permite exceder saldo em aberto');
select throws_ok($$select public.finance_f1(current_setting('f2.org')::uuid,array[current_setting('f2.unit')::uuid],'void',jsonb_build_object('id','ff200000-0000-4000-8000-000000000001','version',2,'reason','Cancelamento indevido','date',current_date,'requestId',extensions.gen_random_uuid()))$$,'22023',null,'título parcialmente pago não pode ser cancelado');
select throws_ok($$select public.finance_f1(current_setting('f2.org')::uuid,array[current_setting('f2.unit')::uuid],'void',jsonb_build_object('id',(public.finance_f2(current_setting('f2.org')::uuid,current_setting('f2.unit')::uuid,'history','{"title":"ff200000-0000-4000-8000-000000000001"}')#>>'{payments,0,cashEntry}')::uuid,'version',1,'reason','Contorno pela F1','date',current_date,'requestId',extensions.gen_random_uuid()))$$,'22023',null,'baixa não permite estorno sem sua taxa');
select lives_ok($$select public.finance_f2(current_setting('f2.org')::uuid,current_setting('f2.unit')::uuid,'settle',current_setting('f2.pay')::jsonb||'{"id":"ff200000-0000-4000-8000-000000000003","version":2,"principal":"6000","interest":"0","fine":"0","discount":"0","fee":"0"}')$$,'liquida restante');
select is(public.finance_f1(current_setting('f2.org')::uuid,array[current_setting('f2.unit')::uuid],'snapshot',current_setting('f2.query')::jsonb)#>>'{summary,receivable}','0','título integralmente liquidado sai da previsão');
select is(public.finance_f1(current_setting('f2.org')::uuid,array[current_setting('f2.unit')::uuid],'snapshot',current_setting('f2.query')::jsonb||'{"scope":"titles","status":"settled"}')->>'total','1','filtro liquidado funciona');
select set_config('f2.reverse',jsonb_build_object('id','ff200000-0000-4000-8000-000000000004','settlement','ff200000-0000-4000-8000-000000000002','reason','Estorno sintético','date',current_date)::text,true);
select lives_ok($$select public.finance_f2(current_setting('f2.org')::uuid,current_setting('f2.unit')::uuid,'reverse',current_setting('f2.reverse')::jsonb)$$,'estorna baixa e taxa atomicamente');
select lives_ok($$select public.finance_f2(current_setting('f2.org')::uuid,current_setting('f2.unit')::uuid,'reverse',current_setting('f2.reverse')::jsonb)$$,'reenvio do estorno idempotente');
select is(public.finance_f1(current_setting('f2.org')::uuid,array[current_setting('f2.unit')::uuid],'snapshot',current_setting('f2.query')::jsonb)#>>'{summary,receivable}','4000','estorno reabre principal correto');
select is(public.finance_f1(current_setting('f2.org')::uuid,array[current_setting('f2.unit')::uuid],'snapshot',current_setting('f2.query')::jsonb)#>>'{accounts,0,balanceCents}','6000','estorno devolve líquido e taxa');
select lives_ok($$select public.finance_f2(current_setting('f2.org')::uuid,current_setting('f2.unit')::uuid,'reschedule',jsonb_build_object('id','ff200000-0000-4000-8000-000000000005','title','ff200000-0000-4000-8000-000000000001','version',4,'due',current_date+10,'reason','Novo vencimento acordado'))$$,'reagenda saldo parcial com auditoria');
select set_config('f2.series',jsonb_build_object('id','ff200000-0000-4000-8000-000000000006','mode','installments','count',3,'frequency','monthly','entry',current_setting('f2.title')::jsonb||'{"amountCents":"10001","due":"2026-01-31","competence":"2026-01-31"}')::text,true);
select lives_ok($$select public.finance_f2(current_setting('f2.org')::uuid,current_setting('f2.unit')::uuid,'series',current_setting('f2.series')::jsonb)$$,'parcelamento finito e atômico');
select is(public.finance_f2(current_setting('f2.org')::uuid,current_setting('f2.unit')::uuid,'series',current_setting('f2.series')::jsonb)#>>'{items,0,amount}','3334','primeira parcela recebe centavo restante');
select is(public.finance_f2(current_setting('f2.org')::uuid,current_setting('f2.unit')::uuid,'series',current_setting('f2.series')::jsonb)#>>'{items,2,amount}','3333','última parcela preserva soma');
select is(public.finance_f2(current_setting('f2.org')::uuid,current_setting('f2.unit')::uuid,'series',current_setting('f2.series')::jsonb)#>>'{items,1,due}','2026-02-28','ajuste ao fim de fevereiro');
select is(public.finance_f2(current_setting('f2.org')::uuid,current_setting('f2.unit')::uuid,'series',current_setting('f2.series')::jsonb)#>>'{items,2,due}','2026-03-31','março volta ao dia âncora');
select throws_ok($$select public.finance_f2(current_setting('f2.org')::uuid,'cf200000-0000-4000-8000-000000000002','history','{"title":"ff200000-0000-4000-8000-000000000001"}')$$,'42501',null,'isolamento por ministério');
select set_config('request.jwt.claims','{"sub":"af200000-0000-4000-8000-000000000002","role":"authenticated"}',true);
select throws_ok($$select public.finance_f2(current_setting('f2.org')::uuid,current_setting('f2.unit')::uuid,'history','{"title":"ff200000-0000-4000-8000-000000000001"}')$$,'42501',null,'secretaria não lê baixas');
reset role;
select is((select sum(delta_cents) from public.church_ledger_lines where organization_id='bf200000-0000-4000-8000-000000000001'),0::numeric,'partidas balanceadas após baixas e estornos');
select is((select count(*) from private.finance_series_items where series_id='ff200000-0000-4000-8000-000000000006'),3::bigint,'reenvio da série não duplica parcelas');
select is((select sum(amount_cents) from private.finance_entries where id in(select entry_id from private.finance_series_items where series_id='ff200000-0000-4000-8000-000000000006')),10001::numeric,'soma original preservada exatamente');
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"af200000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select is(public.finance_f2(current_setting('f2.org')::uuid,current_setting('f2.unit')::uuid,'activity','{"title":"ff200000-0000-4000-8000-000000000001"}')#>>'{items,0,actorId}','af200000-0000-4000-8000-000000000001','histórico identifica autor da alteração');
select is(public.finance_f2(current_setting('f2.org')::uuid,current_setting('f2.unit')::uuid,'activity','{"title":"ff200000-0000-4000-8000-000000000001"}')#>>'{items,0,changes,due_date,before}',current_date::text,'histórico mantém vencimento anterior');
select is(public.finance_f2(current_setting('f2.org')::uuid,current_setting('f2.unit')::uuid,'activity','{"title":"ff200000-0000-4000-8000-000000000001"}')#>>'{items,0,changes,due_date,after}',(current_date+10)::text,'histórico mantém vencimento novo');
select throws_ok($$select public.finance_f2(current_setting('f2.org')::uuid,'cf200000-0000-4000-8000-000000000002','activity','{"title":"ff200000-0000-4000-8000-000000000001"}')$$,'42501',null,'histórico não atravessa ministério');
select lives_ok($$select public.finance_f1(current_setting('f2.org')::uuid,array[current_setting('f2.unit')::uuid],'catalog','{"id":"df200000-0000-4000-8000-000000000004","kind":"category","name":"Arrecadação","direction":"income"}')$$,'categoria principal');
select lives_ok($$select public.finance_f1(current_setting('f2.org')::uuid,array[current_setting('f2.unit')::uuid],'catalog','{"id":"df200000-0000-4000-8000-000000000005","kind":"category","name":"Dízimos","direction":"income","parent":"df200000-0000-4000-8000-000000000004"}')$$,'subcategoria distinta');
select lives_ok($$select public.finance_f1(current_setting('f2.org')::uuid,array[current_setting('f2.unit')::uuid],'entry',current_setting('f2.title')::jsonb||'{"id":"ff200000-0000-4000-8000-000000000007","category":"df200000-0000-4000-8000-000000000005"}')$$,'lançamento em subcategoria');
select is(public.finance_f1(current_setting('f2.org')::uuid,array[current_setting('f2.unit')::uuid],'snapshot',current_setting('f2.query')::jsonb||'{"category":"df200000-0000-4000-8000-000000000004"}')->>'total','1','categoria principal inclui filhos');
select is(public.finance_f1(current_setting('f2.org')::uuid,array[current_setting('f2.unit')::uuid],'snapshot',current_setting('f2.query')::jsonb||'{"category":"df200000-0000-4000-8000-000000000004","subcategory":"df200000-0000-4000-8000-000000000002"}')->>'total','0','subcategoria exata não ignora categoria');
reset role;
select ok(not has_table_privilege('authenticated','private.finance_entry_history','SELECT'),'auditoria sem leitura direta');
select throws_ok($$update private.finance_entry_history set actor_name='Adulterado' where entry_id='ff200000-0000-4000-8000-000000000001'$$,'42501',null,'histórico não permite reescrita nem pelo caminho administrativo comum');
select throws_ok($$delete from private.finance_entry_history where entry_id='ff200000-0000-4000-8000-000000000001'$$,'42501',null,'histórico não pode ser apagado');
select * from finish();
rollback;
